int spark_ai_agent_is_enabled(const SparkGameComponent* component) {
    auto* self = AsAiAgentComponent(component);
    if (self == nullptr) {
        return 0;

    }
    return self->IsEnabled() ? 1 : 0;
}

void spark_ai_agent_set_enabled(SparkGameComponent* component, int e) {
    auto self = AsAiAgentComponent(component);
    if (self == nullptr) {
        return;

    }
    self->SetEnabled(e);
}

